const ALL_CARDS = [
  ...TRUTH_CLASSIC, ...TRUTH_SPICY, ...TRUTH_TRASH,
  ...DARE_CLASSIC, ...DARE_SPICY, ...DARE_TRASH,
  ...DOUBLE_DARE_CLASSIC, ...DOUBLE_DARE_SPICY, ...DOUBLE_DARE_TRASH,
]

export function truthOrDareForPack(pack: TruthOrDarePack | 'mixed'): TruthOrDareCard[] {
  if (pack === 'mixed') return ALL_CARDS
  return ALL_CARDS.filter(c => c.pack === pack)
}

export function truthOrDareForType(pack: TruthOrDarePack | 'mixed', type: TruthOrDareType): TruthOrDareCard[] {
  return truthOrDareForPack(pack).filter(c => c.type === type)
}
